import UIKit
final class PairGameController: UIViewController {
    private var timer: Timer?
    private(set) var ticks = 0
    func startTimer() {
        timer?.invalidate()
        timer = Timer.scheduledTimer(
            withTimeInterval: 1, repeats: true
        ) { [weak self] _ in
            self?.ticks += 1
        }
    }
    override func viewDidAppear(_ animated: Bool) {
        super.viewDidAppear(animated)
        startTimer()
    }
    override func viewDidDisappear(_ animated: Bool) {
        super.viewDidDisappear(animated)
        timer?.invalidate()
        timer = nil
    }
    deinit { timer?.invalidate() }
}

После повторного start старый timer отключён, callback не удерживает контроллер. Ручной fire проверяет обработчик, но не режим run loop и не автоматические UI-события.

