import Foundation
final class TicketController {
    var didSelect: (() -> Void)?
    func connect() {
        didSelect = { [weak self] in self?.showTicket() }
    }
    func showTicket() { print("Билет") }
    deinit { print("Освобождён") }
}
var controller: TicketController? = TicketController()
weak var probe = controller
controller?.connect()
controller?.didSelect?()
controller = nil
print(probe == nil)

Вывод: Билет, Освобождён, true. Сильное ребро callback → controller разорвано. В настоящем UI дополнительно учитывай другие владельцы, например navigation stack.
